return ['domain'=>'coquille-revue','plural-forms'=>'nplurals=2; plural=n > 1;','language'=>'fr_FR','project-id-version'=>'Coquille Revue 2.6.0','pot-creation-date'=>'2026-10-11T12:25:16+00:00','po-revision-date'=>'2026-10-11 12:00+0200','x-generator'=>'WP-CLI 2.12.0','messages'=>['Coquille Revue'=>'Coquille Revue','https://github.com/Atelier-4F-digital/coquille-revue'=>'https://github.com/Atelier-4F-digital/coquille-revue','On-page content review: highlight text or frame an area, leave a correction, suggestion or question, stored in WordPress.'=>'Relecture de contenu sur les pages : surlignez un texte ou encadrez une zone, laissez une correction, une suggestion ou une question, enregistrée dans WordPress.','Atelier 4F Digital'=>'Atelier 4F Digital','https://atelier4fdigital.com'=>'https://atelier4fdigital.com','Selected text'=>'Texte sélectionné','Selected area (%1$s×%2$s)'=>'Zone sélectionnée (%1$s×%2$s)','quoted text“%s”'=>'« %s »','%1$s — “%2$s”'=>'%1$s — « %2$s »','Send'=>'Envoyer','Sending…'=>'Envoi…','Thank you, your suggestion has been sent'=>'Merci, votre suggestion a été envoyée','Invalid email address.'=>'Adresse e-mail invalide.','Your text is too long.'=>'Votre texte est trop long.','Too many submissions for now, please try again in a few minutes.'=>'Trop d’envois pour le moment, réessayez dans quelques minutes.','Log in to suggest a correction.'=>'Connectez-vous pour proposer une correction.','You are not allowed to suggest a correction.'=>'Vous n’avez pas les droits pour proposer une correction.','Sending failed (error %s).'=>'Envoi impossible (erreur %s).','type of remarkCorrection'=>'Correction','type of remarkSuggestion'=>'Suggestion','type of remarkQuestion'=>'Question','(opens in a new tab)'=>'(s’ouvre dans un nouvel onglet)','Your suggestion is saved with your account name.'=>'Votre suggestion est enregistrée avec le nom de votre compte.','Name and email are optional. The email is only used to let you know when your suggestion is applied, then it is deleted.'=>'Nom et e-mail facultatifs. L’e-mail sert uniquement à vous prévenir quand votre suggestion est appliquée, puis il est effacé.','Name is optional.'=>'Nom facultatif.','The IP address is kept for %d day to fight spam.'=>'L’adresse IP est conservée %d jour contre le spam.' . "\0" . 'L’adresse IP est conservée %d jours contre le spam.','Suggestions may be processed with an AI assistant.'=>'Les suggestions peuvent être traitées avec un assistant IA.','Review mode'=>'Mode relecture','Help us improve this page'=>'Aidez-nous à améliorer cette page','Spotted a typo, some wording to rephrase or an area to improve? Turn on review mode to leave us a suggestion right on the page.'=>'Vous avez repéré une coquille, un texte à reformuler ou une zone à améliorer ? Activez le mode relecture pour nous laisser une suggestion directement sur la page.','Keyboard shortcut: %s'=>'Raccourci clavier : %s','keyboard keyShift'=>'Maj','Start reviewing'=>'Commencer la relecture','%1$s plugin · by %2$s'=>'Extension %1$s · proposée par %2$s','Review toolbar'=>'Barre de relecture','Review mode — logged in as %s'=>'Mode relecture — connecté en tant que %s','Select some text'=>'Sélectionnez du texte','or %s over an area'=>'ou %s sur une zone','click and drag'=>'clic + glisser','With the keyboard: select the text, then press Enter'=>'Au clavier : sélectionnez le texte, puis appuyez sur Entrée','leave review modeStop'=>'Arrêter','Close'=>'Fermer','Your name (optional)'=>'Votre nom (facultatif)','Your email (optional)'=>'Votre e-mail (facultatif)','Privacy'=>'Confidentialité','Your suggestion'=>'Votre suggestion','Your suggestion…'=>'Votre suggestion…','Enter to send · Shift+Enter for a new line · Esc to cancel'=>'Entrée pour envoyer · Maj+Entrée pour aller à la ligne · Échap pour annuler','Press Enter or the Send button to send'=>'Touche Entrée ou bouton « Envoyer » pour envoyer','Type of remark'=>'Type de remarque','Cancel'=>'Annuler','You must be logged in to do this.'=>'Vous devez être connecté pour effectuer cette action.','Sorry, you are not allowed to do this.'=>'Désolé, vous n’avez pas l’autorisation d’effectuer cette action.','Suspicious request.'=>'Requête suspecte.','The %s field is too short.'=>'Le champ %s est trop court.','Invalid page address.'=>'Adresse de page invalide.','Characters not allowed.'=>'Caractères non autorisés.','Invalid position in the page.'=>'Position dans la page invalide.','Too many submissions, please try again later.'=>'Trop d’envois, réessayez plus tard.','The annotation could not be saved.'=>'L’annotation n’a pas pu être enregistrée.','Invalid status.'=>'Statut invalide.','Annotation not found.'=>'Annotation introuvable.','[Coquille Revue] %1$d new annotation on %2$s'=>'[Coquille Revue] %1$d nouvelle annotation sur %2$s' . "\0" . '[Coquille Revue] %1$d nouvelles annotations sur %2$s','%d new annotation to review.'=>'%d nouvelle annotation à relire.' . "\0" . '%d nouvelles annotations à relire.','Hello,'=>'Bonjour,','The suggestion you left on %1$s on the site “%2$s” has been applied. Thank you for your review, it really helps.'=>'La suggestion que vous avez laissée le %1$s sur le site « %2$s » a été appliquée. Merci pour votre relecture, c’est précieux.','If you did not make this suggestion, please ignore this message.'=>'Si vous n’êtes pas à l’origine de cette suggestion, ignorez ce message.','The %s team'=>'L’équipe de %s','[%s] Your suggestion has been applied, thank you!'=>'[%s] Votre suggestion a été appliquée, merci !','The IP address is used to limit spam and is deleted after %d day.'=>'L’adresse IP sert à limiter le spam et elle est effacée au bout de %d jour.' . "\0" . 'L’adresse IP sert à limiter le spam et elle est effacée au bout de %d jours.','When a visitor suggests a correction with the Coquille Revue proofreading tool, we store the text concerned and the suggestion, the page address, their name and email address if they give them (optional), and their IP address.'=>'Quand un visiteur propose une correction avec l’outil de relecture Coquille Revue, nous enregistrons le texte concerné et sa suggestion, l’adresse de la page, son nom et son adresse e-mail s’il les indique (facultatifs), ainsi que son adresse IP.','The text, the suggestion and the name are visible to the editors and administrators of the site; the email and the IP address to administrators only. To apply the corrections, the text, the suggestion and the name may be sent to an artificial intelligence assistant (for example Claude, by Anthropic); the email and the IP address never are.'=>'Le texte, la suggestion et le nom sont visibles par les éditeurs et les administrateurs du site ; l’e-mail et l’adresse IP par les administrateurs seulement. Pour appliquer les corrections, le texte, la suggestion et le nom peuvent être transmis à un assistant d’intelligence artificielle (par exemple Claude, d’Anthropic) ; l’e-mail et l’adresse IP ne le sont jamais.','The email is only used to let the person know when their suggestion is applied: it is deleted, along with the name, within a day after the suggestion is processed, and after %d month at the latest.'=>'L’e-mail sert uniquement à prévenir la personne quand sa suggestion est appliquée : il est effacé, avec le nom, dans la journée qui suit le traitement de la suggestion, et au plus tard au bout de %d mois.' . "\0" . 'L’e-mail sert uniquement à prévenir la personne quand sa suggestion est appliquée : il est effacé, avec le nom, dans la journée qui suit le traitement de la suggestion, et au plus tard au bout de %d mois.','When a visitor suggests a correction with the Coquille Revue proofreading tool, we store the text concerned and the suggestion, the page address, their name if they give it (optional), and their IP address.'=>'Quand un visiteur propose une correction avec l’outil de relecture Coquille Revue, nous enregistrons le texte concerné et sa suggestion, l’adresse de la page, son nom s’il l’indique (facultatif), ainsi que son adresse IP.','The text, the suggestion and the name are visible to the editors and administrators of the site; the IP address to administrators only. To apply the corrections, the text, the suggestion and the name may be sent to an artificial intelligence assistant (for example Claude, by Anthropic); the IP address never is.'=>'Le texte, la suggestion et le nom sont visibles par les éditeurs et les administrateurs du site ; l’adresse IP par les administrateurs seulement. Pour appliquer les corrections, le texte, la suggestion et le nom peuvent être transmis à un assistant d’intelligence artificielle (par exemple Claude, d’Anthropic) ; l’adresse IP ne l’est jamais.','The name is deleted within a day after the suggestion is processed, and after %d month at the latest.'=>'Le nom est effacé dans la journée qui suit le traitement de la suggestion, et au plus tard au bout de %d mois.' . "\0" . 'Le nom est effacé dans la journée qui suit le traitement de la suggestion, et au plus tard au bout de %d mois.','Proofreading suggestions'=>'Suggestions de relecture','Page'=>'Page','Original text'=>'Texte d’origine','proposed textSuggestion'=>'Suggestion','Name'=>'Nom','Email'=>'E-mail','IP address'=>'Adresse IP','Date'=>'Date','Coquille Revue: the text of the suggestions is kept, with no link to the person anymore.'=>'Coquille Revue : le texte des suggestions est conservé, sans plus aucun lien avec la personne.','Mode'=>'Mode','Type'=>'Type','Author'=>'Auteur','Status'=>'Statut','Anonymous'=>'Anonyme','Coquille Revue — %s export'=>'Coquille Revue — export %s','Generated on %1$s — %2$d annotation · %3$s'=>'Généré le %1$s — %2$d annotation · %3$s' . "\0" . 'Généré le %1$s — %2$d annotations · %3$s','No annotations with this status.'=>'Aucune annotation avec ce statut.','set the statusPending'=>'En attente','set the statusIn progress'=>'En cours','set the statusApplied'=>'Appliqué','set the statusRejected'=>'Rejeté','set the statusArchive'=>'Archiver','set the status back to pendingRestor